<script setup lang="ts">
import { Head, Link, router } from '@inertiajs/vue3';
import { computed, reactive } from 'vue';
import ErpLayout from '@/Layouts/ErpLayout.vue';
import type { CustomerArAdjustmentIndexProps, CustomerSettlementStatus } from '@/Types/customer-settlement';
defineOptions({ layout: ErpLayout });
const props = defineProps<CustomerArAdjustmentIndexProps>();
const filters = reactive({ ...props.filters });
const pages = computed(() => { const values: number[] = []; for (let page = Math.max(1, props.documents.meta.current_page - 2); page <= Math.min(props.documents.meta.last_page, props.documents.meta.current_page + 2); page += 1) values.push(page); return values; });
const visit = (page = 1): void => { const query: Record<string, string | number> = { page, per_page: filters.per_page }; if (filters.search.trim()) query.search = filters.search.trim(); if (filters.branch_id) query.branch_id = filters.branch_id; if (filters.customer_id) query.customer_id = filters.customer_id; if (filters.status) query.status = filters.status; if (filters.direction) query.direction = filters.direction; router.get(route('customer-ar-adjustments.index'), query, { preserveState: true, preserveScroll: true, replace: true }); };
const reset = (): void => router.get(route('customer-ar-adjustments.index'));
const money = (value: string): string => new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 6 }).format(Number(value));
const date = (value: string | null): string => value ? new Intl.DateTimeFormat('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }).format(new Date(`${value}T00:00:00`)) : '—';
const statusClass = (status: CustomerSettlementStatus): string => status === 'posted' ? 'bg-success-50 text-success-700' : status === 'reversed' || status === 'cancelled' ? 'bg-error-50 text-error-700' : status === 'approved' ? 'bg-blue-50 text-blue-700' : 'bg-gray-100 text-gray-700';
</script>
<template><Head title="Customer AR Adjustments" /><div class="space-y-6">
<div class="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><h1 class="text-2xl font-semibold text-gray-900 dark:text-white">Customer AR Adjustments</h1><p class="mt-1 text-sm text-gray-500">Controlled debit and credit adjustments outside the invoice workflow.</p></div><Link v-if="can.create" :href="route('customer-ar-adjustments.create')" class="rounded-lg bg-brand-500 px-4 py-2.5 text-center text-sm font-medium text-white">Create Adjustment</Link></div>
<div class="rounded-2xl border border-gray-200 bg-white p-5 dark:border-gray-800 dark:bg-gray-900"><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-6"><input v-model="filters.search" placeholder="Adjustment or customer" class="h-11 rounded-lg border border-gray-300 bg-transparent px-3 dark:border-gray-700 dark:text-white xl:col-span-2" /><select v-model="filters.branch_id" class="h-11 rounded-lg border border-gray-300 bg-transparent px-3 dark:border-gray-700 dark:text-white"><option :value="null">All branches</option><option v-for="branch in branches" :key="branch.id" :value="branch.id">{{ branch.name }}</option></select><select v-model="filters.customer_id" class="h-11 rounded-lg border border-gray-300 bg-transparent px-3 dark:border-gray-700 dark:text-white"><option :value="null">All customers</option><option v-for="customer in customers" :key="customer.id" :value="customer.id">{{ customer.name }}</option></select><select v-model="filters.direction" class="h-11 rounded-lg border border-gray-300 bg-transparent px-3 dark:border-gray-700 dark:text-white"><option value="">All directions</option><option v-for="direction in directions" :key="direction.value" :value="direction.value">{{ direction.label }}</option></select><select v-model="filters.status" class="h-11 rounded-lg border border-gray-300 bg-transparent px-3 dark:border-gray-700 dark:text-white"><option value="">All statuses</option><option v-for="status in statuses" :key="status.value" :value="status.value">{{ status.label }}</option></select></div><div class="mt-4 flex justify-end gap-2"><button class="rounded-lg border border-gray-300 px-4 py-2.5 text-sm" @click="reset">Reset</button><button class="rounded-lg bg-brand-500 px-4 py-2.5 text-sm font-medium text-white" @click="visit(1)">Filter</button></div></div>
<div class="overflow-hidden rounded-2xl border border-gray-200 bg-white dark:border-gray-800 dark:bg-gray-900"><div class="overflow-x-auto"><table class="min-w-[1000px] divide-y divide-gray-200 dark:divide-gray-800"><thead class="bg-gray-50"><tr><th class="px-5 py-3 text-left text-xs uppercase text-gray-500">Adjustment</th><th class="px-5 py-3 text-left text-xs uppercase text-gray-500">Customer</th><th class="px-5 py-3 text-left text-xs uppercase text-gray-500">Direction</th><th class="px-5 py-3 text-left text-xs uppercase text-gray-500">Offset Account</th><th class="px-5 py-3 text-left text-xs uppercase text-gray-500">Posting Date</th><th class="px-5 py-3 text-right text-xs uppercase text-gray-500">Amount</th><th class="px-5 py-3 text-left text-xs uppercase text-gray-500">Status</th><th class="px-5 py-3 text-right text-xs uppercase text-gray-500">Actions</th></tr></thead><tbody class="divide-y divide-gray-100"><tr v-if="documents.data.length === 0"><td colspan="8" class="px-5 py-12 text-center text-sm text-gray-500">No AR adjustments found.</td></tr><tr v-for="document in documents.data" :key="document.id"><td class="px-5 py-4"><Link :href="route('customer-ar-adjustments.show', document.id)" class="font-medium text-brand-600">{{ document.adjustment_number ?? `Draft #${document.id}` }}</Link><p class="text-xs text-gray-500">{{ date(document.adjustment_date) }}</p></td><td class="px-5 py-4"><p class="text-sm font-medium">{{ document.customer_name }}</p><p class="text-xs text-gray-500">{{ document.customer_code }} · {{ document.branch?.name }}</p></td><td class="px-5 py-4"><span :class="['rounded-full px-2.5 py-1 text-xs font-medium', document.direction === 'debit' ? 'bg-warning-50 text-warning-700' : 'bg-success-50 text-success-700']">{{ document.direction_label }}</span></td><td class="px-5 py-4 text-sm">{{ document.offset_account?.code }} — {{ document.offset_account?.name }}</td><td class="px-5 py-4 text-sm">{{ date(document.posting_date) }}</td><td class="px-5 py-4 text-right text-sm font-semibold">{{ document.currency_code }} {{ money(document.amount) }}</td><td class="px-5 py-4"><span :class="['rounded-full px-2.5 py-1 text-xs font-medium', statusClass(document.status)]">{{ document.status_label }}</span></td><td class="px-5 py-4 text-right"><Link :href="route('customer-ar-adjustments.show', document.id)" class="text-sm font-medium text-brand-600">View</Link><Link v-if="document.can.update" :href="route('customer-ar-adjustments.edit', document.id)" class="ml-3 text-sm">Edit</Link></td></tr></tbody></table></div><div class="flex items-center justify-between border-t border-gray-200 px-5 py-4"><p class="text-sm text-gray-500">Showing {{ documents.meta.from ?? 0 }}–{{ documents.meta.to ?? 0 }} of {{ documents.meta.total }}</p><div v-if="documents.meta.last_page > 1" class="flex gap-1"><button :disabled="documents.meta.current_page <= 1" class="rounded-lg border border-gray-300 px-3 py-2 text-sm disabled:opacity-50" @click="visit(documents.meta.current_page - 1)">Previous</button><button v-for="page in pages" :key="page" :class="['rounded-lg px-3 py-2 text-sm', page === documents.meta.current_page ? 'bg-brand-500 text-white' : 'border border-gray-300']" @click="visit(page)">{{ page }}</button><button :disabled="documents.meta.current_page >= documents.meta.last_page" class="rounded-lg border border-gray-300 px-3 py-2 text-sm disabled:opacity-50" @click="visit(documents.meta.current_page + 1)">Next</button></div></div></div>
</div></template>
